pub enum Tree<A> {
    Leaf,
    Node(Box<Tree<A>>, A, Box<Tree<A>>),
}

pub fn mirror<A>(t: Tree<A>) -> Tree<A> {
    match t {
        Tree::Leaf => Tree::Leaf,
        Tree::Node(l, x, r) => {
            let mirrored_right = mirror(*r);
            let mirrored_left = mirror(*l);
            Tree::Node(Box::new(mirrored_right), x, Box::new(mirrored_left))
        }
    }
}
